function personAttendanceHtml(d){const p=d.person,days=['L','M','X','J','V','S','D'];const first=new Date(`${state.month}-01T12:00:00`),start=(first.getDay()+6)%7,last=new Date(first.getFullYear(),first.getMonth()+1,0).getDate(),cells=[];for(let i=0;i<start;i++)cells.push('<div class="cal-day muted"></div>');for(let day=1;day<=last;day++){const date=`${state.month}-${String(day).padStart(2,'0')}`,row=d.attendance.find(a=>a.date===date),cls=row?.status==='Puntual'?'ok':row?.status==='Tardanza'?'late':row?.status==='Inasistencia'?'absent':row?'permission':'';cells.push(`<div class="cal-day" data-day-detail="${date}" data-person="${p.id}"><div class="cal-num">${day}</div>${row?`<span class="cal-dot ${cls}"></span><div class="cal-note">${esc(row.status)}<br>${esc(row.in||'')}</div>`:'<div class="cal-note">Sin jornada</div>'}</div>`)}return `<div class="grid two"><div>${card('Calendario diario',`${state.month} · jornada ${DATA.meta.attendanceSchedule}`,`<div class="calendar">${days.map(x=>`<div class="cal-head">${x}</div>`).join('')}${cells.join('')}</div><div id="day-detail" class="day-detail"><h4>Seleccione un día</h4><p>Podrá ver ingreso, salida, incidencia y responsabilidades relacionadas.</p></div>`)}</div><div>${card('Resumen mensual','Asistencia y permanencia',`<div class="mini-grid"><div class="mini-stat"><span>Puntual</span><strong>${d.attendanceSummary.Puntual}</strong></div><div class="mini-stat"><span>Tardanzas</span><strong>${d.attendanceSummary.Tardanza}</strong></div><div class="mini-stat"><span>Inasistencias</span><strong>${d.attendanceSummary.Inasistencia}</strong></div><div class="mini-stat"><span>Permisos/comisiones</span><strong>${d.attendanceSummary.Permiso+d.attendanceSummary.Comisión}</strong></div></div>${donut(d.attendanceSummary.punctuality,'puntualidad','mes seleccionado')}`)}</div></div>`}
function personDocumentsSummary(d){return `<div class="grid two"><div>${card('Documentos vinculados','Abra cualquier documento en el editor',`<div class="task-list">${d.documents.map(x=>`<div class="task" data-open-doc="${x.id}" style="cursor:pointer"><div class="task-top"><div class="task-title">${esc(x.id)} · ${esc(x.type)}</div>${badge(x.status,x.status==='Atendido'?'success':x.status==='Derivado'?'info':'warning')}</div><div class="task-meta"><span>${esc(x.subject)}</span><span>${esc(x.date)}</span></div></div>`).join('')||'<div class="empty">Sin documentos.</div>'}</div>`,`<button class="btn accent" data-action="new-document">✎ Crear documento</button>`)}</div><div>${card('Flujo de trabajo documental','Elaboración, revisión, firma, registro y derivación',procedureFlow('documentos'))}</div></div>`}
function agendaHtml(p){const items=p.tasks.map((t,i)=>({date:t.deadline||`2026-09-${20+i}`,title:t.title,type:i%2?'Evidencia':'Meta'}));return card('Agenda del servidor','Hitos, entregables y vencimientos',table(['Fecha','Tipo','Actividad'],items.map(x=>[esc(x.date),badge(x.type,'info'),esc(x.title)])))}

