function budgetTabs(){return `<div class="tabs"><button class="tab ${state.budgetTab==='explorador'?'active':''}" data-budget-tab="explorador">Explorador</button><button class="tab ${state.budgetTab==='simulador'?'active':''}" data-budget-tab="simulador">Mover / modificar</button><button class="tab ${state.budgetTab==='proyeccion'?'active':''}" data-budget-tab="proyeccion">Proyección</button><button class="tab ${state.budgetTab==='clasificadores'?'active':''}" data-budget-tab="clasificadores">Clasificadores</button></div>`}
async function renderBudget(){
  const d=await getBudget(state.profileId),t=d.totals,rows=[...d.rows],focus=state.selectedCenterCode||state.filters.centerCode;
  const bars=[...rows].sort((a,b)=>a.execution-b.execution).slice(0,12).map(c=>({label:c.code,value:c.execution,name:c.name,action:{route:'centro',filters:{centerCode:c.code}}}));
  let body='';
  if(state.budgetTab==='explorador')body=`<div class="grid two"><div>${card('Centros con menor ejecución','Haga clic en una barra para abrir el centro de costo y todos sus desgloses.',barChart(bars,{max:100}),`<div class="insight-title">Regla de lectura</div><p>La ejecución baja es una señal de seguimiento. El detalle muestra clasificadores, obligaciones, POI, proyección y margen potencialmente evaluable.</p>`)}</div><div>${card('Proyección de cierre','Presupuesto del ámbito visible',donut(pct(t.projected,t.pim),'proyección',money(t.projected),{route:'presupuesto',filters:{tab:'proyeccion'}}),`<div class="recommend"><span>!</span><span>Use el Laboratorio financiero para responder “si necesito X, ¿de dónde conviene obtenerlo y qué afectaría?”.</span></div><div style="margin-top:8px"><button class="btn accent" data-route="financiamiento">Abrir laboratorio financiero</button></div>`)}</div></div>${card('Ejecución por centro de costo','Clic en cualquier fila para abrir el panel completo del centro.',table(['Centro de costo','PIM','Certificado','Compromiso','Devengado','Proyección','Ejecución','Riesgo'],rows.map(c=>[`<span class="table-title">${esc(c.code)} · ${esc(c.name)}</span>`,money(c.pim),money(c.certified),money(c.committed),money(c.accrued),money(c.projected),`${c.execution}%`,riskBadge(c.risk)]),{clickable:true,attrs:i=>`data-center="${rows[i].code}"`}),`<div class="source-note">El centro de costo se mantiene diferenciado de la unidad orgánica y de los códigos que utilicen otros sistemas. El mapeo debe ser explícito.</div>`)}`;
  if(state.budgetTab==='simulador')body=budgetTransferBuilder(rows);
  if(state.budgetTab==='proyeccion')body=`<div class="grid two-equal">${card('PIM vs proyección','Centros con mayor brecha al cierre',barChart([...rows].map(c=>({label:c.code,value:Math.max(0,c.pim-c.projected),name:c.name,action:{route:'centro',filters:{centerCode:c.code}}})).sort((a,b)=>b.value-a.value).slice(0,12),{max:null}),`<div class="insight-title">Interpretación</div><p>La brecha proyectada requiere distinguir imposibilidad de ejecución, programación futura, obligaciones y restricciones.</p>`)}${card('Ejecución proyectada','Porcentaje de cierre por centro',barChart([...rows].map(c=>({label:c.code,value:pct(c.projected,c.pim),name:c.name,action:{route:'centro',filters:{centerCode:c.code}}})).sort((a,b)=>a.value-b.value).slice(0,12),{max:100}))}</div>`;
  if(state.budgetTab==='clasificadores')body=card('Clasificación económica consolidada','Distribución estimada del PIM visible por grandes categorías',classifiersAggregate(rows));
  $('#view').innerHTML=`${pageHead('Presupuesto institucional','Explore, simule y explique la ejecución hasta el centro de costo, clasificador, actividad POI e impacto operativo.',`<span class="institution-ribbon">${rows.length} centros visibles · ${esc(d.updated)}</span><button class="btn" data-action="print-view">${icon('print')} Reporte</button><button class="btn accent" data-action="assistant" data-prompt="¿Cómo va la ejecución presupuestal, qué riesgos ves y dónde debo entrar?">✦ Analizar con IA</button>`)}<div class="grid kpi">${kpi('PIA',money(t.pia),'Presupuesto inicial',null,'₴')}${kpi('PIM',money(t.pim),'Presupuesto modificado',t.certification,'₴')}${kpi('Devengado',money(t.accrued),`${t.execution}% del PIM`,t.execution,'◴')}${kpi('Pagado',money(t.paid),`${t.payment}% del PIM`,t.payment,'⇄')}</div>${budgetTabs()}${body}`;
  if(focus)setTimeout(()=>openCenterModal(focus),0);
}
function classifiersAggregate(rows){const sums={'2.1':0,'2.3':0,'2.6':0,'Otros':0};rows.forEach(c=>centerModel(c.code)?.classifiers.forEach(x=>sums[x.code]=(sums[x.code]||0)+x.pim));return `<div class="grid two-equal">${barChart(Object.entries(sums).map(([code,value])=>({label:code,value,name:code})),{max:null})}<div class="meta-list">${Object.entries(sums).map(([code,value])=>`<div class="meta-row"><span>${code}</span><strong>${money(value)}</strong></div>`).join('')}</div></div>`}
function budgetTransferBuilder(rows){return `<div class="funding-lab"><div class="lab-controls"><h3 style="margin-top:0">Simular movimiento</h3><div class="field"><label>Centro de costo origen</label><select id="move-source" class="select">${rows.map(c=>`<option value="${c.code}">${c.code} · ${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Centro de costo destino</label><select id="move-dest" class="select">${rows.map(c=>`<option value="${c.code}" ${c.code==='1.10.04'?'selected':''}>${c.code} · ${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Monto (S/ M)</label><input id="move-amount" class="input" type="number" step="0.05" min="0" value="0.30"></div><button class="btn primary" style="width:100%;justify-content:center" data-action="simulate-transfer">Calcular impacto</button><div class="source-note" style="margin-top:10px">El cálculo es un escenario what-if. No altera el presupuesto ni registra una nota modificatoria.</div></div><div id="transfer-output">${card('Antes de mover','Seleccione origen, destino y monto. El resultado mostrará disponibilidad potencial, impacto POI, fuente/rubro, restricciones y ruta del procedimiento.',procedureFlow('presupuesto'))}</div></div>`}

async function renderCenter(){
  const code=state.selectedCenterCode||state.filters.centerCode;
  if(!code){ navigate('presupuesto'); return; }
  const c=centerModel(code);
  if(!c){ navigate('presupuesto'); return; }
  const relatedUnit=DATA.orgUnits.find(u=>u.costCenter===code);
  const ranking=recommendFunding(.30,code).slice(0,5);
  const poiTable=table(
    ['Actividad','Avance físico','Avance financiero','Estado'],
    c.activities.map(a=>[
      `<span class="table-title">${esc(a.code)}</span><div class="table-sub">${esc(a.name)}</div>`,
      `${a.physical}%`,`${a.financial}%`,badge(a.status,a.status==='En riesgo'?'danger':'info')
    ]),
    {clickable:true,attrs:i=>`data-action="assistant" data-prompt="Analiza la actividad POI ${esc(c.activities[i].code)} ${esc(c.activities[i].name)} del centro ${esc(c.code)}"`}
  );
  const classifierTable=table(
    ['Clasificador','Concepto','Participación','PIM','Restricción'],
    c.classifiers.map(x=>[
      esc(x.code),esc(x.name),`${x.share}%`,money(x.pim),badge(x.restriction,x.restriction==='Alta'?'danger':'warning')
    ])
  );
  const lineTable=table(
    ['Línea','Concepto','PIM','Certificado','Compromiso','Devengado','Proyección','Evaluable','Condición'],
    (c.budgetLines||[]).map(x=>[
      `<strong>${esc(x.code)}</strong>`,esc(x.name),money(x.pim),money(x.certified),money(x.committed),money(x.accrued),money(x.projected),money(x.evaluable),badge(x.restriction,x.restriction==='Restringido'||x.restriction==='Alta'?'danger':'warning')
    ])
  );
  const fundingTable=table(
    ['Origen potencial','Margen evaluable','Ejecución','Riesgo','Puntaje'],
    ranking.map(x=>[
      `<span class="table-title">${esc(x.code)} · ${esc(x.name)}</span><div class="table-sub">${esc(x.source)}</div>`,
      money(x.available),`${x.execution}%`,riskBadge(x.risk),`${x.score}/100`
    ]),
    {clickable:true,attrs:i=>`data-center="${ranking[i].code}"`}
  );
  const restrictions=`<div class="task-list">${c.restrictions.map(x=>`<div class="task"><div class="task-title">${esc(x)}</div></div>`).join('')}</div>
    <div style="margin-top:10px"><button class="btn accent" data-action="assistant" data-prompt="¿Por qué no puedo asumir como libre el saldo del centro ${esc(c.code)}?">✦ Explicar procedimiento</button></div>`;
  $('#view').innerHTML=`
    ${pageHead(
      `${c.code} · ${c.name}`,
      'Panel completo del centro de costo: ejecución, clasificadores, POI, proyección, obligaciones y escenarios.',
      `<button class="btn" data-route="presupuesto">← Volver</button><button class="btn" data-action="print-view">${icon('print')} Reporte</button><button class="btn accent" data-action="assistant" data-prompt="Analiza el centro de costo ${esc(c.code)} ${esc(c.name)} y dime riesgos y recomendaciones">✦ Analizar con IA</button>`,
      [{label:'Presupuesto',route:'presupuesto'},{label:c.code}]
    )}
    <div class="detail-hero">
      <div>
        <h2>${esc(c.name)}</h2>
        <p>${esc(c.source)} · rubro ${esc(c.rubro)} · ${c.activities.length} actividades POI modeladas</p>
        <div class="hero-badges" style="margin-top:8px"><span class="badge info">PIM ${money(c.pim)}</span>${riskBadge(c.risk)}<span class="badge warning">Evaluable ${money(c.evaluable)}</span></div>
      </div>
      <div class="detail-actions">
        ${relatedUnit?`<button class="btn" data-ui-action='${encode({route:'unidad',filters:{unitId:relatedUnit.id}})}'>Abrir unidad</button>`:''}
        <button class="btn accent" data-route="financiamiento">Buscar alternativas</button>
      </div>
    </div>
    <div class="grid kpi">
      ${kpi('PIM',money(c.pim),'Presupuesto modificado',null,'₴')}
      ${kpi('Devengado',money(c.accrued),`${c.execution}%`,c.execution,'◴')}
      ${kpi('Obligación proyectada',money(c.obligation),'Proyección menos devengado',null,'▤')}
      ${kpi('Margen evaluable',money(c.evaluable),'Sujeto a validación',null,'↔')}
    </div>
    <div class="grid two">
      <div class="stack">
        ${card('Evolución financiera','Serie acumulada hasta la proyección',barChart(c.monthly.map(x=>({label:x.m,value:x.value,name:x.m})),{max:100}))}
        ${card('Actividades POI vinculadas','Haga clic en una actividad para pedir análisis contextual.',poiTable)}
      </div>
      <div class="stack">
        ${card('Clasificadores económicos','Distribución del PIM',classifierTable)}
        ${card('Condiciones para modificar','La disponibilidad contable no implica disponibilidad jurídica u operativa',restrictions)}
      </div>
    </div>
    ${card('Desglose económico de trabajo','La vista desagrega el centro por líneas económicas y separa saldo aparente de margen evaluable. La estructura definitiva se sincroniza con el clasificador/SIAF del ejercicio.',lineTable,`<div class="source-note">Los códigos se muestran a nivel de categoría/genérica/subgenérica de trabajo. Antes de una modificación formal debe validarse la específica, meta, fuente/rubro y estructura presupuestaria vigente.</div>`)}
    ${card('Alternativas de financiamiento para una necesidad de S/ 0.30 M','Ranking preliminar de otros centros; el laboratorio permite cambiar el monto.',fundingTable,`<button class="btn accent" data-route="financiamiento">Abrir Laboratorio financiero →</button>`)}
  `;
}

function openCenterModal(code){const c=centerModel(code);if(!c)return;showModal(`${c.code} · ${c.name}`,'Resumen ejecutivo del centro de costo',`<div class="grid kpi" style="grid-template-columns:repeat(4,1fr)">${kpi('PIM',money(c.pim),'',null,'₴')}${kpi('Devengado',money(c.accrued),'',c.execution,'◴')}${kpi('Proyección',money(c.projected),'',pct(c.projected,c.pim),'◇')}${kpi('Evaluable',money(c.evaluable),'',null,'↔')}</div><div class="grid two-equal">${card('Clasificadores','',table(['Código','Concepto','PIM'],c.classifiers.map(x=>[x.code,esc(x.name),money(x.pim)])))}${card('POI','',table(['Actividad','Físico','Financiero'],c.activities.map(x=>[esc(x.code),`${x.physical}%`,`${x.financial}%`])) )}</div><div class="sticky-actions"><button class="btn" data-action="modal-close">Cerrar</button><button class="btn primary" data-ui-action='${encode({route:'centro',filters:{centerCode:code}})}'>Abrir panel completo</button></div>`,true)}

async function renderFundingLab(){const d=await getBudget(state.profileId),rows=d.rows;const target=state.filters.targetCode||state.fundingTarget||rows.find(c=>c.code==='1.10.04')?.code||rows[0]?.code;const amount=Number(state.filters.amount||.50);const recs=recommendFunding(amount,target).filter(r=>rows.some(c=>c.code===r.code)).slice(0,12);$('#view').innerHTML=`${pageHead('Laboratorio financiero','Responda preguntas de decisión: cuánto se necesita, de dónde podría salir, qué afectaría y qué pasos siguen.',`<button class="btn" data-action="print-view">${icon('print')} Reporte</button><button class="btn accent" data-action="assistant" data-prompt="Necesito S/ ${amount} millones. ¿De dónde conviene obtenerlo y qué afectaría?">✦ Preguntar a IA</button>`)}<div class="funding-lab"><div class="lab-controls"><h3 style="margin-top:0">Nueva necesidad</h3><div class="field"><label>Centro / proyecto destino</label><select id="fund-target" class="select">${rows.map(c=>`<option value="${c.code}" ${c.code===target?'selected':''}>${c.code} · ${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Monto requerido (S/ M)</label><input id="fund-amount" class="input" type="number" min="0" step="0.05" value="${amount}"></div><div class="field"><label>Prioridad</label><select id="fund-priority" class="select"><option>Crítica</option><option>Alta</option><option>Media</option></select></div><button class="btn primary" style="width:100%;justify-content:center" data-action="funding-recalculate">Buscar mejores alternativas</button><div class="source-note" style="margin-top:10px">El ranking pondera margen evaluable, riesgo, compatibilidad de fuente/rubro y capacidad proyectada. El centro de costo es una vista gerencial: OPP debe validar la estructura presupuestaria formal, clasificadores y nivel de modificación antes de cualquier trámite o registro oficial.</div></div><div><div class="grid kpi">${kpi('Necesidad',money(amount),'Monto solicitado',null,'₴')}${kpi('Alternativas',String(recs.length),'Candidatas visibles',null,'↔')}${kpi('Cobertura máxima',money(recs[0]?.available||0),'Mejor origen individual',null,'◇')}${kpi('Destino',target,'Centro de costo',null,'◎')}</div>${card('Ranking de fuentes potenciales','Seleccione una alternativa para comparar el antes y después.',`<div class="task-list">${recs.map((r,i)=>`<div class="candidate ${state.fundingSelected===r.code?'selected':''}" data-funding-source="${r.code}"><div class="candidate-head"><div><h4>${i+1}. ${esc(r.code)} · ${esc(r.name)}</h4><p>${esc(r.source)} · ${esc(r.impact)}${r.lineCode?`<br>Origen sugerido: ${esc(r.lineCode)} · ${esc(r.lineName)} (evaluable ${money(r.lineAvailable)})`:''}</p></div><div class="score">${r.score}</div></div><div class="task-meta"><span>Evaluable ${money(r.available)}</span><span>Ejecución ${r.execution}%</span><span>Riesgo ${r.risk}</span></div></div>`).join('')}</div>`,`<div class="insight-title">Interpretación</div><p>La alternativa con mayor puntaje no se convierte automáticamente en una recomendación final. Debe revisarse el impacto sobre POI, obligaciones, contratos y restricciones normativas.</p>`)}<div id="funding-detail"></div></div></div>`;if(state.fundingSelected)setTimeout(()=>renderFundingDetail(state.fundingSelected,target,amount),0)}
function renderFundingDetail(source,target,amount){const s=transferScenario(source,target,amount),box=$('#funding-detail');if(!box||!s)return;box.innerHTML=`${card(`Escenario ${s.classification}`,'Comparación origen → destino',`<div class="scenario-compare"><div class="before-after"><h4>Origen · ${esc(s.source.code)} ${esc(s.source.name)}</h4><div class="impact-list"><div class="impact"><span>PIM antes</span><strong>${money(s.sourceBefore.pim)}</strong></div><div class="impact"><span>PIM después</span><strong>${money(s.sourceAfter.pim)}</strong></div><div class="impact"><span>Ejecución proyectada</span><strong>${s.sourceAfter.execution}%</strong></div><div class="impact"><span>Margen evaluable</span><strong>${money(s.source.evaluable)}</strong></div>${s.sourceLine?`<div class="impact"><span>Línea de origen sugerida</span><strong>${esc(s.sourceLine.code)} · ${esc(s.sourceLine.name)}</strong></div>`:''}</div></div><div class="before-after"><h4>Destino · ${esc(s.dest.code)} ${esc(s.dest.name)}</h4><div class="impact-list"><div class="impact"><span>PIM antes</span><strong>${money(s.destBefore.pim)}</strong></div><div class="impact"><span>PIM después</span><strong>${money(s.destAfter.pim)}</strong></div><div class="impact"><span>Ejecución proyectada</span><strong>${s.destAfter.execution}%</strong></div><div class="impact"><span>Monto recibido</span><strong>${money(s.amount)}</strong></div></div></div></div>${s.flags.length?`<div class="recommend danger" style="margin-top:10px"><span>!</span><span>${s.flags.map(esc).join('<br>')}</span></div>`:`<div class="recommend success" style="margin-top:10px"><span>✓</span><span>El escenario pasa a evaluación técnica de detalle.</span></div>`}<h4 style="font-size:9px">Impacto POI potencial en el origen</h4>${table(['Actividad','Físico','Financiero','Estado'],s.affectedPoi.map(a=>[esc(a.name),`${a.physical}%`,`${a.financial}%`,esc(a.status)]))}<h4 style="font-size:9px">Procedimiento</h4>${procedureFlow('presupuesto')}<div class="sticky-actions"><button class="btn" data-ui-action='${encode({route:'centro',filters:{centerCode:source}})}'>Abrir origen</button><button class="btn" data-ui-action='${encode({route:'centro',filters:{centerCode:target}})}'>Abrir destino</button><button class="btn accent" data-action="assistant" data-prompt="Explica este escenario de mover ${money(amount)} desde ${esc(source)} hacia ${esc(target)} y qué riesgos debo revisar">✦ Explicar con IA</button><button class="btn primary" data-action="save-scenario">Guardar escenario</button></div>`)}`;state.lastScenario=s}

async function renderInvestments(){const d=await getInvestments(),items=d.items;$('#view').innerHTML=`${pageHead('Inversiones','Cartera navegable con avance físico, financiero, temporal, contractual, brecha, hitos y escenarios presupuestales.',`<button class="btn" data-action="print-view">${icon('print')} Reporte</button><button class="btn accent" data-action="assistant" data-prompt="¿Qué inversiones requieren atención y por qué?">✦ Analizar cartera</button>`)}<div class="grid kpi">${kpi('Cartera',String(items.length),'Inversiones visibles',null,'◇')}${kpi('Riesgo alto',String(items.filter(i=>i.risk==='Alto').length),'Prioridad de revisión',null,'!')}${kpi('Brecha agregada',money(items.reduce((a,i)=>a+Number(i.gap||0),0)),'Modelada',null,'₴')}${kpi('Avance financiero',`${fmt(items.reduce((a,i)=>a+i.financial,0)/items.length)}%`,'Promedio',null,'◴')}</div>${card('Comparación físico-financiera','Clic sobre una inversión para abrirla.',multiChart(items.map(i=>({label:i.id,physical:i.physical,financial:i.financial,time:i.time,action:{route:'proyecto',filters:{projectId:i.id}}}))))}${card('Cartera de inversiones','Abra cualquier fila para revisar contrato, hitos, brecha y financiamiento.',table(['ID/CUI','Inversión','PIM','Físico','Financiero','Temporal','Riesgo'],items.map(i=>[`<span class="table-title">${esc(i.id)} · ${esc(i.cui)}</span>`,esc(i.name),money(i.pim),`${i.physical}%`,`${i.financial}%`,`${i.time}%`,riskBadge(i.risk)]),{clickable:true,attrs:i=>`data-project="${items[i].id}"`}))}`}
async function renderProject(){const id=state.selectedProjectId||state.filters.projectId,inv=DATA.investments.find(i=>i.id===id);if(!inv)return navigate('inversiones');const recs=recommendFunding(inv.gap,'1.10.04').slice(0,5);$('#view').innerHTML=`${pageHead(inv.name,'Seguimiento integral de la inversión y su relación con presupuesto, hitos y decisiones de financiamiento.',`<button class="btn" data-route="inversiones">← Cartera</button><button class="btn accent" data-action="assistant" data-prompt="Analiza ${esc(inv.id)} y dime qué pasa si refuerzo su presupuesto">✦ Analizar con IA</button>`,[{label:'Inversiones',route:'inversiones'},{label:inv.id}])}<div class="detail-hero"><div><h2>${esc(inv.id)} · ${esc(inv.cui)}</h2><p>${esc(inv.name)} · responsable ${esc(inv.manager)}</p></div><div class="detail-actions"><button class="btn accent" data-route="financiamiento">Buscar financiamiento</button></div></div><div class="grid kpi">${kpi('PIM',money(inv.pim),'',null,'₴')}${kpi('Físico',`${inv.physical}%`,'Avance',inv.physical,'◇')}${kpi('Financiero',`${inv.financial}%`,'Avance',inv.financial,'◴')}${kpi('Brecha',money(inv.gap),'Necesidad modelada',null,'!')}</div><div class="grid two"><div>${card('Estado comparado','Físico, financiero, temporal y contractual',barChart([{label:'Físico',value:inv.physical},{label:'Financiero',value:inv.financial},{label:'Temporal',value:inv.time},{label:'Contrato',value:inv.contract}],{max:100}),`<div class="recommend ${inv.risk==='Alto'?'danger':''}"><span>!</span><span>Riesgo ${esc(inv.risk)} · siguiente hito: ${esc(inv.nextMilestone)} (${esc(inv.milestoneDate)}).</span></div>`)}</div><div>${card('Posibles fuentes para cubrir la brecha','Ranking preliminar',table(['Centro','Evaluable','Puntaje','Riesgo'],recs.map(r=>[`<span class="table-title">${esc(r.code)} ${esc(r.name)}</span>`,money(r.available),String(r.score),riskBadge(r.risk)]),{clickable:true,attrs:i=>`data-funding-source="${recs[i].code}" data-funding-target="1.10.04" data-funding-amount="${inv.gap}"`}),`<button class="btn accent" data-route="financiamiento">Abrir laboratorio →</button>`)}</div></div>${card('Hito y decisiones siguientes','Trazabilidad operativa',`<div class="flow">${['Revisión de avance','Valorización / hito','Disponibilidad presupuestal','Decisión','Ejecución','Seguimiento'].map((x,i)=>`<span class="flow-step ${i<3?'active':''}">${esc(x)}</span>${i<5?'<span class="flow-arrow">→</span>':''}`).join('')}</div>`)}`}

async function renderRRHH(){const d=await getDashboard(state.profileId),people=d.people.filter(p=>/RECURSOS HUMANOS|ESCALAF|CAPACIT|REMUNER|PENSION|PERSONAL|CONTROL DOCENTE|CONTROL ADMINISTRATIVO|SEGURIDAD|DISCIPLIN/.test(p.unit));const regs=DATA.regimes,total=regs.reduce((a,x)=>a+x.count,0);$('#view').innerHTML=`${pageHead('Recursos Humanos','Personas, regímenes, asistencia, metas GdR, áreas y carga operativa.',`<button class="btn" data-route="asistencia">◷ Asistencia</button><button class="btn accent" data-action="assistant" data-prompt="¿Qué riesgos de Recursos Humanos requieren atención y qué área los concentra?">✦ Analizar RR. HH.</button>`)}<div class="grid kpi">${kpi('Personal institucional',total.toLocaleString('es-PE'),'Docente y administrativo',null,'♙')}${kpi('Perfiles visibles',String(people.length),'Según ámbito activo',null,'♙')}${kpi('Puntualidad',`${DATA.attendanceSummary?.punctuality||d.attendance.punctuality}%`,'Seguimiento diario',d.attendance.punctuality,'◷')}${kpi('GdR',`${fmt(people.reduce((a,p)=>a+p.gdrProgress,0)/Math.max(people.length,1))}%`,'Avance medio del ámbito',null,'▰')}</div><div class="grid two"><div>${card('Regímenes / grupos','Distribución institucional de referencia',barChart(regs.map(r=>({label:r.name.slice(0,12),value:r.count,name:r.name})),{max:null}))}</div><div>${card('Áreas de RR. HH.','Abra la organización para navegar por responsables y servidores',`<div class="task-list">${DATA.orgUnits.filter(u=>u.parentId==='ORG-unidad-de-recursos-humanos').map(u=>`<div class="task" data-unit="${u.id}" style="cursor:pointer"><div class="task-title">${esc(u.name)}</div><div class="task-meta"><span>Responsable ${esc(u.responsibleName||'—')}</span><span>${u.peopleCount||0} personas</span></div></div>`).join('')}</div>`)}</div></div>${card('Equipo visible','Abra cualquier servidor',table(['Servidor','Puesto','Unidad','GdR','Puntualidad'],people.slice(0,40).map(p=>[`<span class="task-person" data-person="${p.id}">${esc(p.name)}</span>`,esc(p.position),esc(p.unit),`${p.gdrProgress}%`,`${p.attendanceSummary?.punctuality||0}%`])))} `}

