async function renderAssets(){const a=await getAssets();$('#view').innerHTML=`${pageHead('Control patrimonial','Bienes, regularización, mantenimiento e incidencias.',`<button class="btn" data-action="print-view">${icon('print')} Reporte</button><button class="btn accent" data-action="assistant" data-prompt="¿Qué tipo de bienes requiere mayor atención patrimonial?">✦ Analizar</button>`)}<div class="grid kpi">${kpi('Bienes',a.reduce((s,x)=>s+x.count,0).toLocaleString('es-PE'),'Inventario visible',null,'⬡')}${kpi('Mantenimiento',String(a.reduce((s,x)=>s+x.maintenance,0)),'Pendientes / programados',null,'⚙')}${kpi('Incidencias',String(a.reduce((s,x)=>s+x.incidents,0)),'Revisión',null,'!')}${kpi('Regularización media',`${fmt(a.reduce((s,x)=>s+x.regularized,0)/a.length)}%`,'',null,'✓')}</div>${card('Estado por tipo','Clic para ampliar',barChart(a.map(x=>({label:x.type.slice(0,12),value:x.regularized,name:x.type})),{max:100}))}${card('Detalle patrimonial','',table(['Tipo','Cantidad','Regularización','Mantenimiento','Incidencias'],a.map(x=>[esc(x.type),x.count.toLocaleString('es-PE'),`${x.regularized}%`,String(x.maintenance),String(x.incidents)])))} `}
