function renderAccounting(){const c=DATA.accounting;$('#view').innerHTML=`${pageHead('Contabilidad','Control, devengado, integración, observaciones y cierre.',`<button class="btn accent" data-action="assistant" data-prompt="¿Qué está retrasando el devengado o cierre contable?">✦ Analizar</button>`)}<div class="grid kpi">${kpi('Pendiente devengado',money(c.pendingAccrual),'',null,'▤')}${kpi('Integrado',`${c.integrated}%`,'',c.integrated,'✓')}${kpi('Observaciones',String(c.observations),'',null,'!')}${kpi('Cierre',`${c.closingProgress}%`,'',c.closingProgress,'◴')}</div>${card('Cadena contable','',procedureFlow('contabilidad'))}`}
function renderServices(){const s=DATA.services;$('#view').innerHTML=`${pageHead('Servicios Generales','Solicitudes, mantenimiento, transportes, talleres, limpieza y áreas verdes.',`<button class="btn accent" data-action="assistant" data-prompt="¿Qué servicios generales están críticos y dónde debo revisar?">✦ Analizar</button>`)}<div class="grid kpi">${kpi('Solicitudes',String(s.requests),'',null,'⚙')}${kpi('Atendidas',String(s.completed),'',pct(s.completed,s.requests),'✓')}${kpi('Críticas',String(s.critical),'',null,'!')}${kpi('Vehículos disponibles',String(s.vehiclesAvailable),'',null,'◇')}</div>${card('Áreas operativas','',`<div class="task-list">${DATA.orgUnits.filter(u=>u.parentId==='ORG-unidad-de-servicios-generales').map(u=>`<div class="task" data-unit="${u.id}" style="cursor:pointer"><div class="task-title">${esc(u.name)}</div><div class="task-meta"><span>${esc(u.responsibleName||'—')}</span></div></div>`).join('')}</div>`)}`}
async function renderPlanning(){const opp=DATA.orgUnits.find(u=>u.name==='OFICINA DE PLANEAMIENTO Y PRESUPUESTO'),units=opp?childrenOf(opp.id):[];$('#view').innerHTML=`${pageHead('Planeamiento y OPP','Unidades reales, responsables, productos GdR, POI, presupuesto, modernización, estadística y formulación.',`<button class="btn" data-route="presupuesto">₴ Presupuesto</button><button class="btn accent" data-action="assistant" data-prompt="Analiza OPP por unidades y dime qué tareas o riesgos destacan">✦ Analizar OPP</button>`)}<div class="grid three">${units.map(u=>{const b=unitBudget(u).totals;return `<div class="report-card" data-unit="${u.id}"><div class="ico">◎</div><h3>${esc(u.name)}</h3><p>Responsable: ${esc(u.responsibleName||'—')}<br>${u.peopleCount||0} personas · ${u.costCenter?`CC ${u.costCenter}`:'sin CC individualizado'}</p><div class="report-actions">${u.costCenter?badge(`Ejec. ${b.execution||0}%`,b.execution<60?'warning':'success'):badge('Gestión funcional','info')}</div></div>`}).join('')}</div>${card('Productos y tareas observadas en OPP','Construidos desde las metas GdR del ZIP',`<div class="task-list">${units.flatMap(u=>(u.sampleProducts||[]).slice(0,2).map(x=>`<div class="task" data-unit="${u.id}" style="cursor:pointer"><div class="task-title">${esc(x)}</div><div class="task-meta"><span>${esc(u.name)}</span></div></div>`)).join('')}</div>`)}`}
async function renderProcesses(){const items=await getProcesses();const selected=state.filters.process;$('#view').innerHTML=`${pageHead('Procesos y mejora','AS-IS → análisis → TO-BE, responsables, SLA, riesgos, controles y puntos de automatización.',`<button class="btn accent" data-action="assistant" data-prompt="¿Qué proceso tiene mayor riesgo y por qué?">✦ Analizar procesos</button>`)}${card('Procesos prioritarios','Abra cualquiera para revisar su cuello de botella',table(['Proceso','Responsable','Avance','SLA','Riesgo','Cuello'],items.map(x=>[`<span class="table-title">${esc(x.name)}</span>`,esc(x.owner),`${x.progress}%`,`${x.sla}%`,riskBadge(x.risk),esc(x.bottleneck)]),{clickable:true,attrs:i=>`data-process="${i}"`}))}${selected?card(`Flujo · ${selected}`,'Secuencia conceptual',procedureFlow(selected)):''}`}

function getDocStore(){try{return JSON.parse(localStorage.getItem('sig_v4_docs')||'{}')}catch{return {}}}
function setDocStore(o){localStorage.setItem('sig_v4_docs',JSON.stringify(o))}
function hydrateDocument(doc,person){const store=getDocStore();if(store[doc.id])return store[doc.id];const tpl=personTemplates(person)[0];return {...doc,title:doc.subject,body:`${tpl.body.replace('[asunto]',doc.subject).replace('[servidor]',person?.name||'')}`,workflow:['Elaboración'],updated:doc.date,ownerId:doc.personId}}
function createDraft(templateId){const p=personById(currentProfile().personId||state.selectedPersonId)||state.bootstrap.people[0],tpl=personTemplates(p).find(t=>t.id===templateId)||personTemplates(p)[0],id=`BOR-${Date.now().toString().slice(-8)}-2026`;const doc={id,personId:p.id,type:tpl.name,subject:tpl.subject.replace('[asunto]','Nuevo asunto'),status:'Borrador',date:today,expedient:'',routeExpected:p.unit,source:'Mesa de trabajo',title:tpl.subject,body:tpl.body.replace('[servidor]',p.name),workflow:['Elaboración'],updated:new Date().toISOString(),ownerId:p.id};const s=getDocStore();s[id]=doc;setDocStore(s);state.selectedDocumentId=id;return doc}
function allVisibleDocuments(){const profile=currentProfile(),ids=new Set(state.bootstrap.people.map(p=>p.id)),base=DATA.documents.filter(d=>profile.role==='staff'?d.personId===profile.personId:ids.has(d.personId));const store=getDocStore();const extra=Object.values(store).filter(d=>profile.role==='staff'?d.personId===profile.personId:ids.has(d.personId));const map=new Map(base.map(d=>[d.id,d]));extra.forEach(d=>map.set(d.id,d));return [...map.values()].sort((a,b)=>String(b.updated||b.date).localeCompare(String(a.updated||a.date)))}
async function renderDocuments(){const docs=allVisibleDocuments(),p=currentProfile();if(!state.selectedDocumentId)state.selectedDocumentId=docs[0]?.id||null;const selected=docs.find(d=>d.id===state.selectedDocumentId),owner=selected?personById(selected.personId):personById(p.personId);const full=selected?hydrateDocument(selected,owner):null;$('#view').innerHTML=`${pageHead('Documentos y SGDUNT','Elabore, revise, descargue, imprima, envíe a revisión/firma y siga la ruta documental desde la misma mesa de trabajo.',`<button class="btn" data-action="new-document">✎ Nuevo</button><button class="btn" data-action="print-view">${icon('print')} Imprimir vista</button><button class="btn accent" data-action="assistant" data-prompt="¿Qué documentos requieren atención y cuál es su siguiente paso?">✦ Analizar documentos</button>`)}${full?documentWorkspace(full,owner):'<div class="empty">No hay documentos visibles. Cree uno nuevo.</div>'}`}
function documentWorkspace(doc,owner){const templates=personTemplates(owner);return `<div class="editor-layout"><div class="doc-list"><div class="doc-list-head"><button class="btn accent" style="width:100%;justify-content:center" data-action="new-document">✎ Nuevo documento</button></div><div class="doc-items">${allVisibleDocuments().slice(0,50).map(d=>`<div class="doc-item ${d.id===doc.id?'active':''}" data-open-doc="${d.id}"><strong>${esc(d.id)} · ${esc(d.type)}</strong><span>${esc(d.subject)}</span><span>${esc(d.status)} · ${esc(d.date||'')}</span></div>`).join('')}</div></div><div class="editor-pane"><div class="editor-toolbar"><button class="tool-btn" data-editor="bold"><b>B</b></button><button class="tool-btn" data-editor="italic"><i>I</i></button><button class="tool-btn" data-editor="insertUnorderedList">• Lista</button><button class="tool-btn" data-action="save-doc">Guardar</button><button class="tool-btn" data-action="download-doc">${icon('download')} Word</button><button class="tool-btn" data-action="print-doc">${icon('print')} PDF/Imprimir</button></div><div class="editor-meta"><div><label>Tipo</label><select id="doc-type">${templates.map(t=>`<option value="${t.id}" ${doc.type===t.name?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div><label>Estado</label><select id="doc-status"><option ${doc.status==='Borrador'?'selected':''}>Borrador</option><option ${doc.status==='En revisión'?'selected':''}>En revisión</option><option ${doc.status==='Pendiente de firma'?'selected':''}>Pendiente de firma</option><option ${doc.status==='Firmado'?'selected':''}>Firmado</option><option ${doc.status==='Derivado'?'selected':''}>Derivado</option><option ${doc.status==='Atendido'?'selected':''}>Atendido</option></select></div><div style="grid-column:1/-1"><label>Asunto</label><input id="doc-subject" value="${esc(doc.subject)}"></div></div><div id="document-sheet" class="document-sheet" contenteditable="true">${esc(doc.body)}</div></div><div class="doc-side"><h3>Flujo y acciones</h3><div class="meta-list"><div class="meta-row"><span>Responsable</span><strong>${esc(owner?.name||'—')}</strong></div><div class="meta-row"><span>Unidad</span><strong>${esc(owner?.unit||'—')}</strong></div><div class="meta-row"><span>Expediente</span><strong>${esc(doc.expedient||'Pendiente')}</strong></div><div class="meta-row"><span>Ruta esperada</span><strong>${esc(doc.routeExpected||owner?.unit||'—')}</strong></div></div><h4>Estado del flujo</h4>${workflowHtml(doc)}<h4>Acciones</h4><div class="task-list"><button class="btn" data-action="send-review">Enviar a revisión</button><button class="btn" data-action="request-signature">Solicitar firma</button>${isManager()?`<button class="btn success" data-action="sign-doc">✓ Firmar con DNIe</button>`:''}<button class="btn" data-action="register-sgdunt">Registrar / derivar SGDUNT</button><button class="btn" data-action="send-doc">Preparar envío</button></div><div class="source-note" style="margin-top:10px">En producción, la firma y el registro deben ejecutarse mediante los servicios autorizados. Esta interfaz mantiene separados elaboración, aprobación, firma y trámite formal.</div></div></div>`}
function workflowHtml(doc){const steps=['Elaboración','Revisión','Aprobación','Firma','Registro / derivación','Atención / archivo'];const wf=doc.workflow||['Elaboración'];return `<div class="workflow">${steps.map((s,i)=>{const done=wf.includes(s)||wf.some(x=>x.startsWith(s.split(' / ')[0])),active=i===Math.min(wf.length,steps.length-1);return `<div class="workflow-step ${done?'done':''} ${active?'active':''}"><div class="n">${i+1}</div><div><strong>${esc(s)}</strong><span>${done?'Registrado en el flujo':'Pendiente'}</span></div></div>`}).join('')}</div>`}
function saveCurrentDocument(){const id=state.selectedDocumentId;if(!id)return;const docs=allVisibleDocuments(),base=docs.find(d=>d.id===id),owner=personById(base?.personId),doc=hydrateDocument(base,owner);doc.subject=$('#doc-subject')?.value||doc.subject;doc.status=$('#doc-status')?.value||doc.status;doc.body=$('#document-sheet')?.innerText||doc.body;doc.updated=new Date().toISOString();const store=getDocStore();store[id]=doc;setDocStore(store);toast('Documento guardado','success')}
function updateDocWorkflow(step,status){saveCurrentDocument();const store=getDocStore(),doc=store[state.selectedDocumentId]||hydrateDocument(allVisibleDocuments().find(d=>d.id===state.selectedDocumentId),personById(allVisibleDocuments().find(d=>d.id===state.selectedDocumentId)?.personId));doc.workflow=doc.workflow||['Elaboración'];if(!doc.workflow.includes(step))doc.workflow.push(step);if(status)doc.status=status;doc.updated=new Date().toISOString();store[doc.id]=doc;setDocStore(store);toast(`Documento: ${status||step}`,'success');renderDocuments()}
function downloadCurrentDoc(){saveCurrentDocument();const doc=getDocStore()[state.selectedDocumentId];if(!doc)return;const html=`<html><head><meta charset="utf-8"><style>body{font-family:Arial;font-size:12pt;line-height:1.5;margin:2.5cm}h1{font-size:14pt}</style></head><body><h1>${esc(doc.type)} ${esc(doc.id)}</h1><p><b>Asunto:</b> ${esc(doc.subject)}</p><div>${esc(doc.body).replace(/\n/g,'<br>')}</div></body></html>`;downloadBlob(new Blob([html],{type:'application/msword'}),`${doc.id}.doc`)}
function printCurrentDoc(){saveCurrentDocument();const doc=getDocStore()[state.selectedDocumentId];if(!doc)return;const w=window.open('','_blank');w.document.write(`<html><head><title>${esc(doc.id)}</title><style>body{font-family:Arial;font-size:12pt;line-height:1.5;margin:2.5cm}h1{font-size:14pt}</style></head><body><h1>${esc(doc.type)} ${esc(doc.id)}</h1><p><b>Asunto:</b> ${esc(doc.subject)}</p><div>${esc(doc.body).replace(/\n/g,'<br>')}</div><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}

async function renderGantt(){const d=await getDashboard(state.profileId);let tasks=d.tasks;if(state.filters.personId)tasks=tasks.filter(t=>t.personId===state.filters.personId);if(state.filters.unitId){const ids=new Set([state.filters.unitId,...descendantIds(state.filters.unitId)]);tasks=tasks.filter(t=>ids.has(personById(t.personId)?.unitId))}const start=new Date('2026-09-01T12:00:00'),end=new Date('2026-10-31T12:00:00'),total=(end-start)/86400000;const rows=tasks.slice(0,24).map((t,i)=>{const due=new Date(`${t.deadline||'2026-09-30'}T12:00:00`),dur=7+(i%12),s=new Date(Math.max(start.getTime(),due.getTime()-dur*86400000)),left=clamp((s-start)/86400000/total*100,0,100),width=clamp(dur/total*100,3,35);return `<div style="display:grid;grid-template-columns:250px 1fr;gap:8px;align-items:center;margin:7px 0"><div><div class="table-title task-person" data-person="${t.personId}">${esc(t.person)}</div><div class="table-sub">${esc(t.title).slice(0,95)}</div></div><div style="height:22px;background:#f2f4f7;border-radius:6px;position:relative"><div style="position:absolute;left:${left}%;width:${width}%;height:100%;background:${t.priority==='Alta'?'#D8261A':t.priority==='Media'?'#E6AD09':'#12377B'};border-radius:6px;opacity:.88" title="${esc(t.deadline||'')}"></div></div></div>`}).join('');$('#view').innerHTML=`${pageHead('Gantt y tareas','Cronograma operativo conectado con metas GdR, responsable, evidencia y plazo.',`<button class="btn" data-action="print-view">${icon('print')} Reporte</button><button class="btn accent" data-action="assistant" data-prompt="¿Qué tareas críticas pueden afectar resultados o presupuesto?">✦ Analizar</button>`)}<div class="grid kpi">${kpi('Tareas',String(tasks.length),'Visibles',null,'▰')}${kpi('Alta prioridad',String(tasks.filter(t=>t.priority==='Alta').length),'',null,'!')}${kpi('En revisión',String(tasks.filter(t=>t.status==='En revisión').length),'',null,'✓')}${kpi('Avance medio',`${fmt(tasks.reduce((a,t)=>a+t.progress,0)/Math.max(tasks.length,1))}%`,'',null,'◴')}</div>${card('Cronograma','Haga clic en el responsable para abrir su mesa de trabajo.',rows)}`}
async function renderNorms(){const d=await getNorms();$('#view').innerHTML=`${pageHead('Normativa y reglas','Normas de referencia y explicación de su impacto sobre los módulos.',`<button class="btn accent" data-action="assistant" data-prompt="Explícame la norma y el procedimiento aplicable a una modificación presupuestaria">✦ Preguntar a IA</button>`)}<div class="grid two-equal">${[...NORMATIVE_RULES,...d.filter(n=>!NORMATIVE_RULES.some(x=>x.title===n.title))].map(n=>`<div class="norm-item"><strong>${esc(n.title)}</strong><span>${esc(n.summary||n.topic||'')}</span><span>${esc(n.effect||n.impact||'')}</span><div style="margin-top:7px"><button class="btn sm" data-action="assistant" data-prompt="Explícame cómo se aplica ${esc(n.title)} en este sistema">Explicar</button></div></div>`).join('')}</div>${card('Procedimientos explicables','La IA puede explicar por qué se hace así y llevar al módulo correspondiente.',`<div class="grid three">${['Presupuesto','Contratación','Documentos y firma'].map(t=>`<div class="report-card" data-procedure="${t}"><div class="ico">§</div><h3>${esc(t)}</h3><p>Abra el flujo, las reglas y los puntos de decisión humana.</p></div>`).join('')}</div>`)}`}
async function renderReports(){const cats=reportCatalog();$('#view').innerHTML=`${pageHead('Centro de reportes','Genere, descargue o imprima reportes del ámbito autorizado.',`<button class="btn accent" data-action="assistant" data-prompt="¿Qué reporte me conviene mostrar al Director ahora?">✦ Recomendar reporte</button>`)}<div class="report-grid">${cats.map(r=>`<div class="report-card" data-report="${r.id}"><div class="ico">▥</div><h3>${esc(r.name)}</h3><p>${esc(r.desc)}</p><div class="report-actions"><button class="btn sm" data-report-print="${r.id}">Imprimir</button><button class="btn sm" data-report-csv="${r.id}">CSV</button></div></div>`).join('')}</div>`}
function generateReportData(id){const p=currentProfile();if(id==='presupuesto'){const rows=state.bootstrap.costCenters;return {title:'Ejecución presupuestal por centro de costo',headers:['Código','Centro','PIA','PIM','Certificado','Compromiso','Devengado','Pagado','Proyección','Ejecución'],rows:rows.map(c=>[c.code,c.name,c.pia,c.pim,c.certified,c.committed,c.accrued,c.paid,c.projected,c.execution])}}if(id==='asistencia'){const people=state.bootstrap.people;return {title:'Asistencia y permanencia',headers:['Servidor','Unidad','Puntualidad','Tardanzas','Inasistencias'],rows:people.map(x=>[x.name,x.unit,x.attendanceSummary?.punctuality||0,x.attendanceSummary?.late||x.attendanceSummary?.Tardanza||0,x.attendanceSummary?.absence||x.attendanceSummary?.Inasistencia||0])}}if(id==='gdr'){const people=state.bootstrap.people;return {title:'Seguimiento de metas GdR',headers:['Servidor','Unidad','Meta','Peso','Avance','Plazo','Evidencia'],rows:people.flatMap(x=>x.tasks.map(t=>[x.name,x.unit,t.title,t.weight,t.progress,t.deadline,t.evidence]))}}if(id==='inversiones')return {title:'Seguimiento de inversiones',headers:['ID','CUI','Inversión','PIM','Físico','Financiero','Temporal','Contractual','Brecha','Riesgo'],rows:DATA.investments.map(i=>[i.id,i.cui,i.name,i.pim,i.physical,i.financial,i.time,i.contract,i.gap,i.risk])};if(id==='contrataciones')return {title:'Contrataciones y requerimientos',headers:['Código','Objeto','Unidad','Monto','Etapa','Riesgo'],rows:DATA.procurements.map(x=>[x.id,x.item,x.unit,x.amount,x.stage,x.risk])};if(id==='documentos')return {title:'Documentos y expedientes',headers:['Documento','Tipo','Asunto','Estado','Fecha','Expediente'],rows:allVisibleDocuments().map(x=>[x.id,x.type,x.subject,x.status,x.date,x.expedient])};const d=state.bootstrap;return {title:'Reporte ejecutivo DGA–OPP',headers:['Indicador','Valor'],rows:[['Perfil',p.name],['Ámbito',p.scope],['Personas visibles',d.people.length],['Centros de costo',d.costCenters.length],['Corte',DATA.meta.cutoff]]}}
function reportModal(id){const r=generateReportData(id);showModal(r.title,`Generado para ${currentProfile().scope}`,`${table(r.headers,r.rows.slice(0,80).map(row=>row.map(x=>esc(x))))}<div class="sticky-actions"><button class="btn" data-report-csv="${id}">Descargar CSV</button><button class="btn primary" data-report-print="${id}">Imprimir / PDF</button></div>`,true)}
function exportReportCsv(id){const r=generateReportData(id),csv=[r.headers,...r.rows].map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\n');downloadBlob(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),`${r.title.replace(/[^a-z0-9]+/gi,'_')}.csv`)}
function printReport(id){const r=generateReportData(id),w=window.open('','_blank');w.document.write(`<html><head><meta charset="utf-8"><title>${esc(r.title)}</title><style>body{font-family:Arial;margin:25px;color:#222}h1{font-size:18px;color:#12377B}p{font-size:11px}table{border-collapse:collapse;width:100%;font-size:9px}th,td{border:1px solid #ddd;padding:5px;text-align:left}th{background:#f2f4f7}</style></head><body><h1>${esc(r.title)}</h1><p>Ámbito: ${esc(currentProfile().scope)} · corte ${esc(DATA.meta.cutoff)}</p><table><thead><tr>${r.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${r.rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}

function procedureFlow(topic){const m=procedureMap(topic);return `<div class="flow">${m.steps.map((s,i)=>`<span class="flow-step ${i<3?'active':''}">${esc(s)}</span>${i<m.steps.length-1?'<span class="flow-arrow">→</span>':''}`).join('')}</div><div class="source-note" style="margin-top:9px">${m.norms.slice(0,3).map(n=>esc(n.title)).join(' · ')}</div>`}
function renderInsight(){const d=state.insight;if(!d)return navigate('dashboard');let chart='';if(d.chart?.type==='bars')chart=barChart((d.chart.items||[]).map(x=>({...x,action:x.action||null})),{max:100});if(d.chart?.type==='multi')chart=multiChart(d.chart.items||[]);if(d.chart?.type==='attendance')chart=barChart(d.chart.items||[],{max:100});$('#view').innerHTML=`${pageHead(d.title||'Dashboard generado',d.subtitle||'Análisis contextual generado por el asistente.',`<button class="btn" data-action="print-view">${icon('print')} Imprimir</button><button class="btn accent" data-action="assistant">✦ Continuar con IA</button>`)}${d.kpis?.length?`<div class="grid kpi">${d.kpis.map(k=>kpi(k.label,k.value,'',null,'◇')).join('')}</div>`:''}<div class="grid two"><div>${chart?card('Visualización','Dashboard generado desde la consulta',chart):''}</div><div>${card('Interpretación','',`<p>${esc(d.explanation||'')}</p>${d.recommendations?.length?`<div class="task-list">${d.recommendations.map(x=>`<div class="task"><div class="task-title">${esc(x)}</div></div>`).join('')}</div>`:''}`)}</div></div>${d.table?card('Detalle','',table(d.table.headers,d.table.rows.map(r=>r.map(x=>esc(x))))):''}`}

async function render(){cardSeq=0;sidebar();topbar();const route=state.route;try{if(route==='dashboard')return renderDashboard();if(route==='organizacion')return renderOrganization();if(route==='unidad')return renderUnit();if(route==='persona')return renderPersonPage();if(route==='asistencia')return renderAttendance();if(route==='presupuesto')return renderBudget();if(route==='centro')return renderCenter();if(route==='financiamiento')return renderFundingLab();if(route==='inversiones')return renderInvestments();if(route==='proyecto')return renderProject();if(route==='rrhh')return renderRRHH();if(route==='abastecimiento')return renderProcurement();if(route==='patrimonio')return renderAssets();if(route==='tesoreria')return renderTreasury();if(route==='contabilidad')return renderAccounting();if(route==='servicios')return renderServices();if(route==='planeamiento')return renderPlanning();if(route==='procesos')return renderProcesses();if(route==='documentos')return renderDocuments();if(route==='gantt')return renderGantt();if(route==='reportes')return renderReports();if(route==='normativa')return renderNorms();if(route==='insight')return renderInsight();return renderDashboard()}catch(err){$('#view').innerHTML=`${pageHead('No se pudo abrir el módulo',esc(err.message||err))}<div class="recommend danger"><span>!</span><span>${esc(err.message||err)}</span></div>`}}

function assistantShell(){const p=currentProfile();$('#assistant-root').innerHTML=`<div id="assistant-overlay" class="assistant-overlay ${state.assistantOpen?'show':''}"></div><aside class="assistant-drawer ${state.assistantOpen?'open':''}"><div class="assistant-head"><div><h3>✦ Asistente Institucional</h3><p>${esc(p.name)} · ${esc(p.scope)}</p></div><button class="assistant-close" data-action="assistant-close">×</button></div><div class="assistant-context"><span class="context-chip">Módulo: ${esc(routeLabels[state.route]||state.route)}</span><span class="context-chip">Corte: ${esc(DATA.meta.cutoff)}</span><span class="context-chip">Ámbito: ${esc(p.scope)}</span></div><div id="assistant-messages" class="assistant-messages"></div><div class="assistant-suggestions"><button class="suggestion" data-ask="¿Qué debería preocuparme hoy y llévame a revisarlo?">Prioridades de hoy</button><button class="suggestion" data-ask="Necesito S/ 0.5 millones para una prioridad. ¿De dónde conviene obtenerlo y qué afectaría?">Buscar financiamiento</button><button class="suggestion" data-ask="¿Qué centro de costo tiene mayor riesgo de ejecución y por qué?">Riesgo presupuestal</button><button class="suggestion" data-ask="¿Qué documentos están pendientes de firma o revisión?">Documentos</button></div><div class="assistant-input"><textarea id="assistant-query" placeholder="Pregunte por presupuesto, persona, proceso, inversión, documento o procedimiento. Puede decir: 'llévame a ello'."></textarea><button class="send-btn" data-action="assistant-send">➤</button></div></aside>`;renderAssistantMessages()}
function renderAssistantMessages(){const box=$('#assistant-messages');if(!box)return;box.innerHTML=state.messages.length?state.messages.map(m=>m.role==='user'?`<div class="bubble user">${esc(m.text)}</div>`:assistantResultHtml(m.data)).join(''):`<div class="bubble ai"><div class="ai-title">Listo para analizar y navegar</div>Puedo calcular, comparar, explicar el procedimiento y llevarlo al centro de costo, persona, inversión, documento o dashboard que sustenta la respuesta. Pruebe: <strong>“Necesito S/ 500 mil para una inversión crítica, ¿de dónde conviene obtenerlos?”</strong></div>`;box.scrollTop=box.scrollHeight}
function assistantResultHtml(d){return `<div class="bubble ai"><div class="ai-title">${esc(d.title)}</div><div>${esc(d.body)}</div>${d.metrics?.length?`<div class="ai-metrics">${d.metrics.map(m=>`<div class="ai-metric"><span>${esc(m.label)}</span><strong>${esc(m.value)}</strong></div>`).join('')}</div>`:''}${d.recommendations?.length?`<div class="ai-recs"><strong>Recomendaciones</strong><ul>${d.recommendations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<div class="ai-actions">${d.action?`<button class="btn sm primary" data-ai-action='${encode(d.action)}'>${esc(d.action.label||'Abrir')}</button>`:''}${d.dashboard?`<button class="btn sm accent" data-ai-dashboard="1">Visualizar dashboard</button>`:''}${d.procedure?`<button class="btn sm" data-procedure="${esc(d.procedure)}">Ver procedimiento</button>`:''}</div>${d.sources?.length?`<div class="ai-sources">Cortes utilizados: ${d.sources.map(esc).join(' · ')}</div>`:''}</div>`}
function amountFrom(q){const m=String(q).replace(/,/g,'.').match(/(?:S\/\.?\s*)?(\d+(?:\.\d+)?)\s*(MIL|MILLON|MILLONES|M)?/i);if(!m)return null;let v=Number(m[1]);if((m[2]||'').toUpperCase()==='MIL')v/=1000;return v}
function centerFromQuery(q){const uq=q.toUpperCase();return DATA.costCenters.find(c=>uq.includes(c.code.toUpperCase())||uq.includes(c.name.toUpperCase()))}
async function smartAsk(text){const q=String(text||''),uq=q.toUpperCase(),amount=amountFrom(q),center=centerFromQuery(q);
  if(/LLEVAME|LLÉVAME|MUESTRAME ESO|MUÉSTRAME ESO|ABRE ESO/.test(uq)&&state.lastAIAction)return {title:'Navegación preparada',body:'Mantengo el contexto del último análisis y puedo llevarlo directamente al módulo filtrado.',action:state.lastAIAction,dashboard:state.lastAIDashboard,recommendations:['Abra el detalle y continúe consultando desde ese contexto.'],sources:[DATA.meta.cutoff]};
  if((/DE DONDE|DÓNDE|CONVIENE|FINANCIAR|FALTA|NECESITO/.test(uq)&&amount)||(/PROYECTO/.test(uq)&&/PRESUP/.test(uq))){const target=center?.code||'1.10.04',recs=recommendFunding(amount||.5,target).filter(r=>state.bootstrap.costCenters.some(c=>c.code===r.code)).slice(0,5),dash={title:`Alternativas de financiamiento · ${money(amount||.5)}`,subtitle:`Destino ${target}`,kpis:[{label:'Necesidad',value:money(amount||.5)},{label:'Alternativas',value:String(recs.length)},{label:'Mejor cobertura',value:money(recs[0]?.available||0)},{label:'Destino',value:target}],chart:{type:'bars',items:recs.map(r=>({label:r.code,value:r.score,name:r.name,action:{route:'centro',filters:{centerCode:r.code}}}))},table:{headers:['Origen','Evaluable','Puntaje','Riesgo'],rows:recs.map(r=>[`${r.code} ${r.name}`,money(r.available),`${r.score}/100`,r.risk])},explanation:'El ranking no mueve presupuesto. Compara margen potencial, riesgo y compatibilidad; la validación técnica y normativa corresponde a OPP y a las instancias competentes.',recommendations:['Abrir el Laboratorio financiero','Comparar impacto POI y obligaciones del origen','Descartar créditos restringidos antes de formalizar']};return {title:'Alternativas para financiar la necesidad',body:`Para una necesidad de ${money(amount||.5)}, encontré ${recs.length} orígenes potenciales dentro del ámbito visible. La mejor alternativa individual presenta un margen evaluable de ${money(recs[0]?.available||0)}.`,metrics:dash.kpis,recommendations:dash.recommendations,action:{label:'Abrir Laboratorio financiero',route:'financiamiento',filters:{amount:amount||.5,targetCode:target}},dashboard:dash,procedure:'Presupuesto',sources:[`Presupuesto ${DATA.meta.budgetUpdated}`,`POI ${DATA.meta.poiUpdated}`]}}
  if(center){const c=centerModel(center.code),dash={title:`Centro de costo ${c.code}`,subtitle:c.name,kpis:[{label:'PIM',value:money(c.pim)},{label:'Devengado',value:money(c.accrued)},{label:'Ejecución',value:`${c.execution}%`},{label:'Evaluable',value:money(c.evaluable)}],chart:{type:'bars',items:c.monthly.map(x=>({label:x.m,value:x.value}))},table:{headers:['Actividad POI','Físico','Financiero','Estado'],rows:c.activities.map(a=>[a.name,`${a.physical}%`,`${a.financial}%`,a.status])},explanation:'El saldo aparente no se asume como disponible. El centro se analiza con proyección, obligaciones, clasificadores, fuente/rubro y POI.',recommendations:c.restrictions.slice(0,3)};return {title:`Análisis del centro ${c.code}`,body:`${c.name}: PIM ${money(c.pim)}, devengado ${money(c.accrued)}, ejecución ${c.execution}% y margen potencialmente evaluable ${money(c.evaluable)}.`,metrics:dash.kpis,recommendations:dash.recommendations,action:{label:'Abrir centro de costo',route:'centro',filters:{centerCode:c.code}},dashboard:dash,procedure:'Presupuesto',sources:[`Presupuesto ${DATA.meta.budgetUpdated}`]}}
  if(/DOCUMENT|FIRMA|EDITAR|DESCARGAR|IMPRIMIR/.test(uq)){return {title:'Mesa documental',body:'Puede elaborar y editar documentos, guardarlos, descargarlos en formato compatible con Word, imprimirlos/PDF, enviarlos a revisión, solicitar firma y preparar su registro o derivación en SGDUNT.',metrics:[{label:'Documentos visibles',value:String(allVisibleDocuments().length)},{label:'Módulo',value:'Documentos y SGDUNT'}],recommendations:['Abra un documento existente o cree uno desde una plantilla','Use el flujo para separar elaboración, revisión, firma y derivación'],action:{label:'Abrir mesa documental',route:'documentos',filters:{}},procedure:'Documentos',sources:[`SGDUNT ${DATA.meta.sgduntUpdated}`]}}
  if(/REPORTE|INFORME EJECUTIVO|EXPORTAR/.test(uq)){return {title:'Centro de reportes',body:'Puede generar reportes ejecutivos, presupuesto, asistencia, GdR, inversiones, contratación y documentos dentro del ámbito autorizado.',metrics:[{label:'Tipos',value:String(reportCatalog().length)},{label:'Salida',value:'Impresión/PDF y CSV'}],recommendations:['Use el reporte ejecutivo para Dirección','Use ejecución por centro de costo para análisis presupuestal'],action:{label:'Abrir reportes',route:'reportes',filters:{}},sources:[DATA.meta.cutoff]}}
  const res=await askAssistant({profileId:state.profileId,query:q,route:state.route,context:{lastAction:state.lastAIAction,lastDashboard:state.lastAIDashboard}});return res}
async function sendAssistant(q){const text=String(q||$('#assistant-query')?.value||'').trim();if(!text)return;state.messages.push({role:'user',text});renderAssistantMessages();if($('#assistant-query'))$('#assistant-query').value='';const res=await smartAsk(text);state.messages.push({role:'ai',data:res});if(res.action)state.lastAIAction=res.action;if(res.dashboard)state.lastAIDashboard=res.dashboard;renderAssistantMessages()}
function applyAIAction(a){if(!a)return;if(a.route==='insight'&&state.lastAIDashboard){state.insight=state.lastAIDashboard;navigate('insight');return}navigate(a.route||'dashboard',a.filters||{})}

function showModal(title,sub,html,wide=false,full=false){$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal ${wide?'wide':''} ${full?'full':''}"><div class="modal-head"><div><h3>${esc(title)}</h3><span>${esc(sub||'')}</span></div><button class="modal-close" data-action="modal-close">×</button></div><div class="modal-body">${html}</div></div></div>`}
function maximizeCard(id){const c=document.getElementById(id);if(!c)return;showModal($('.card-title',c)?.textContent||'Detalle',$('.card-sub',c)?.textContent||'',`<section class="card"><div class="card-body">${$('.card-body',c)?.innerHTML||''}</div>${$('.card-footer',c)?.outerHTML||''}</section>`,true,true)}
function toast(msg,type=''){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=msg;$('#toast-root').append(el);setTimeout(()=>el.remove(),2800)}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},600)}
function showDayDetail(personId,date){const p=personById(personId),row=DATA.attendance.find(a=>a.personId===personId&&a.date===date),box=$('#day-detail');if(!box)return;box.innerHTML=`<h4>${esc(date)} · ${esc(p?.name||'')}</h4>${row?`<p><strong>${esc(row.status)}</strong> · ingreso ${esc(row.in)} · salida ${esc(row.out)} ${row.lateMinutes?`· ${row.lateMinutes} min tarde`:''}</p><p>${esc(row.note||'Sin observación')}</p>`:'<p>Sin registro laboral para la fecha.</p>'}<div class="insight-title" style="margin-top:8px">Responsabilidades relacionadas</div>${(p?.tasks||[]).slice(0,4).map(t=>`<p>• ${esc(t.title)} · avance ${t.progress}%</p>`).join('')}`}
function procedureModal(topic){const m=procedureMap(topic);showModal(m.title,'Secuencia, normas y puntos de decisión',`${procedureFlow(topic)}<div class="norm-list" style="margin-top:12px">${m.norms.map(n=>`<div class="norm-item"><strong>${esc(n.title)}</strong><span>${esc(n.summary)}</span><span>${esc(n.effect)}</span></div>`).join('')}</div>`,true)}
async function runSearch(q){const box=$('#search-results');if(!box)return;const res=await searchAll(q,state.profileId);box.innerHTML=res.map(x=>`<div class="search-row" data-search-route="${x.route}" data-search-filters='${encode(x.filters||{})}'><strong>${esc(x.title)}</strong><span>${esc(x.type)} · ${esc(x.subtitle)}</span></div>`).join('')||'<div class="search-row"><span>Sin coincidencias.</span></div>';box.classList.add('show')}

function openCommand(){state.commandOpen=true;$('#command-root').innerHTML=`<div class="command-backdrop"><div class="command"><input id="command-input" placeholder="Buscar o ejecutar: presupuesto, servidor, expediente, crear documento…" autofocus><div id="command-results" class="command-results"><div class="command-item" data-route="presupuesto"><strong>Abrir presupuesto</strong><span>Centros de costo, simulación y proyección</span></div><div class="command-item" data-route="financiamiento"><strong>Abrir Laboratorio financiero</strong><span>Buscar fuentes para una necesidad</span></div><div class="command-item" data-action="new-document"><strong>Crear documento</strong><span>Abrir plantilla y editor</span></div><div class="command-item" data-route="reportes"><strong>Centro de reportes</strong><span>Imprimir o exportar información</span></div></div></div></div>`;setTimeout(()=>$('#command-input')?.focus(),20)}
function closeCommand(){state.commandOpen=false;$('#command-root').innerHTML=''}

window.addEventListener('hashchange',()=>{state.route=(location.hash.replace('#/','')||'dashboard').split('?')[0];render()});
document.addEventListener('click',async e=>{
  const route=e.target.closest('[data-route]');if(route){const f=route.dataset.filters?decode(route.dataset.filters):{};navigate(route.dataset.route,f);return}
  const uia=e.target.closest('[data-ui-action]');if(uia){const a=decode(uia.dataset.uiAction);navigate(a.route,a.filters||{});return}
  const chart=e.target.closest('[data-chart-action]');if(chart){const a=decode(chart.dataset.chartAction);navigate(a.route,a.filters||{});return}
  const unit=e.target.closest('[data-unit]');if(unit){state.selectedUnitId=unit.dataset.unit;if(state.route==='organizacion')loadUnitSide(unit.dataset.unit);else navigate('unidad',{unitId:unit.dataset.unit});return}
  const person=e.target.closest('[data-person]');if(person&&person.dataset.person){navigate('persona',{personId:person.dataset.person});return}
  const center=e.target.closest('[data-center]');if(center){navigate('centro',{centerCode:center.dataset.center});return}
  const project=e.target.closest('[data-project]');if(project){navigate('proyecto',{projectId:project.dataset.project});return}
  const max=e.target.closest('[data-maximize]');if(max){maximizeCard(max.dataset.maximize);return}
  const tab=e.target.closest('[data-person-tab]');if(tab){state.personTab=tab.dataset.personTab;renderPersonPage(state.selectedPersonId,state.personTab);return}
  const btab=e.target.closest('[data-budget-tab]');if(btab){state.budgetTab=btab.dataset.budgetTab;renderBudget();return}
  const doc=e.target.closest('[data-open-doc]');if(doc){state.selectedDocumentId=doc.dataset.openDoc;renderDocuments();return}
  const fsource=e.target.closest('[data-funding-source]');if(fsource){state.fundingSelected=fsource.dataset.fundingSource;const target=fsource.dataset.fundingTarget||$('#fund-target')?.value||state.fundingTarget||'1.10.04',amount=Number(fsource.dataset.fundingAmount||$('#fund-amount')?.value||.5);renderFundingDetail(state.fundingSelected,target,amount);return}
  const proc=e.target.closest('[data-procedure]');if(proc){procedureModal(proc.dataset.procedure);return}
  const rep=e.target.closest('[data-report]');if(rep&&!e.target.closest('button')){reportModal(rep.dataset.report);return}
  const rp=e.target.closest('[data-report-print]');if(rp){e.stopPropagation();printReport(rp.dataset.reportPrint);return}
  const rc=e.target.closest('[data-report-csv]');if(rc){e.stopPropagation();exportReportCsv(rc.dataset.reportCsv);return}
  const aiAction=e.target.closest('[data-ai-action]');if(aiAction){state.assistantOpen=false;assistantShell();applyAIAction(decode(aiAction.dataset.aiAction));return}
  const aiDash=e.target.closest('[data-ai-dashboard]');if(aiDash&&state.lastAIDashboard){state.insight=state.lastAIDashboard;state.assistantOpen=false;assistantShell();navigate('insight');return}
  const ask=e.target.closest('[data-ask]');if(ask){state.assistantOpen=true;assistantShell();sendAssistant(ask.dataset.ask);return}
  const sr=e.target.closest('[data-search-route]');if(sr){$('#search-results')?.classList.remove('show');navigate(sr.dataset.searchRoute,decode(sr.dataset.searchFilters));return}
  const act=e.target.closest('[data-action]');if(act){const a=act.dataset.action;
    if(a==='assistant'){state.assistantOpen=true;assistantShell();if(act.dataset.prompt)sendAssistant(act.dataset.prompt);return}
    if(a==='assistant-close'){state.assistantOpen=false;assistantShell();return}
    if(a==='assistant-send'){sendAssistant();return}
    if(a==='profile'){$('#profile-pop')?.classList.toggle('show');return}
    if(a==='modal-close'){$('#modal-root').innerHTML='';return}
    if(a==='mobile-menu'){$('#sidebar').classList.toggle('open');return}
    if(a==='freshness'){showModal('Estado de actualización','Cada fuente conserva su corte propio',`<div class="grid two-equal">${Object.entries({Presupuesto:DATA.meta.budgetUpdated,Asistencia:DATA.meta.attendanceUpdated,SGDUNT:DATA.meta.sgduntUpdated,Inversiones:DATA.meta.investmentsUpdated,POI:DATA.meta.poiUpdated,GdR:DATA.meta.gdrUpdated}).map(([k,v])=>`<div class="report-card"><h3>${esc(k)}</h3><p>${esc(v)}</p></div>`).join('')}</div>`);return}
    if(a==='print-view'){window.print();return}
    if(a==='new-document'){const owner=personById(currentProfile().personId||state.selectedPersonId)||state.bootstrap.people[0],templates=personTemplates(owner);showModal('Nuevo documento','Seleccione una plantilla vinculada con la naturaleza del trabajo',`<div class="report-grid">${templates.map(t=>`<div class="report-card" data-create-template="${t.id}"><div class="ico">${t.icon}</div><h3>${esc(t.name)}</h3><p>${esc(t.subject)}</p></div>`).join('')}</div>`,true);return}
    if(a==='save-doc'){saveCurrentDocument();return}
    if(a==='download-doc'){downloadCurrentDoc();return}
    if(a==='print-doc'){printCurrentDoc();return}
    if(a==='send-review'){updateDocWorkflow('Revisión','En revisión');return}
    if(a==='request-signature'){updateDocWorkflow('Aprobación','Pendiente de firma');return}
    if(a==='sign-doc'){updateDocWorkflow('Firma','Firmado');return}
    if(a==='register-sgdunt'){updateDocWorkflow('Registro / derivación','Derivado');showModal('Registro / derivación','Preparación de interoperabilidad con SGDUNT',`<div class="recommend success"><span>✓</span><span>El documento quedó marcado como derivado dentro del flujo de trabajo. En producción, esta acción debe autenticarse y registrar el trámite mediante el mecanismo autorizado de SGDUNT.</span></div><div class="source-note" style="margin-top:10px">La plataforma no sustituye el registro formal ni inventa un número de expediente.</div>`);return}
    if(a==='send-doc'){toast('Envío preparado para el canal autorizado','success');return}
    if(a==='simulate-transfer'){const s=$('#move-source')?.value,d=$('#move-dest')?.value,amt=Number($('#move-amount')?.value||0),sc=transferScenario(s,d,amt);state.lastScenario=sc;$('#transfer-output').innerHTML=sc?scenarioFullHtml(sc):'<div class="recommend danger">No se pudo calcular.</div>';return}
    if(a==='funding-recalculate'){state.fundingTarget=$('#fund-target')?.value;state.filters.amount=Number($('#fund-amount')?.value||.5);state.fundingSelected=null;renderFundingLab();return}
    if(a==='save-scenario'){if(!state.lastScenario){toast('No hay escenario calculado','warning');return}const arr=JSON.parse(localStorage.getItem('sig_v4_scenarios')||'[]');arr.unshift({...state.lastScenario,savedAt:new Date().toISOString()});localStorage.setItem('sig_v4_scenarios',JSON.stringify(arr.slice(0,30)));toast('Escenario guardado','success');return}
  }
  const ct=e.target.closest('[data-create-template]');if(ct){const doc=createDraft(ct.dataset.createTemplate);$('#modal-root').innerHTML='';navigate('documentos',{docId:doc.id});return}
  const prof=e.target.closest('[data-profile]');if(prof){state.profileId=prof.dataset.profile;localStorage.setItem('sig_v4_profile',state.profileId);state.bootstrap=await getBootstrap(state.profileId);state.selectedUnitId=null;state.selectedPersonId=state.bootstrap.profile.personId||null;state.route='dashboard';location.hash='#/dashboard';state.messages=[];render();return}
  const day=e.target.closest('[data-day-detail]');if(day){showDayDetail(day.dataset.person,day.dataset.dayDetail);return}
  if(e.target.id==='assistant-overlay'){state.assistantOpen=false;assistantShell()}
  if(e.target.classList.contains('command-backdrop'))closeCommand();
});
function scenarioFullHtml(s){return `${card(`Escenario ${s.classification}`,'Análisis origen → destino',`<div class="scenario-compare"><div class="before-after"><h4>Origen · ${esc(s.source.code)} ${esc(s.source.name)}</h4><div class="impact-list"><div class="impact"><span>PIM antes</span><strong>${money(s.sourceBefore.pim)}</strong></div><div class="impact"><span>PIM después</span><strong>${money(s.sourceAfter.pim)}</strong></div><div class="impact"><span>Proyección</span><strong>${s.sourceAfter.execution}%</strong></div>${s.sourceLine?`<div class="impact"><span>Línea sugerida</span><strong>${esc(s.sourceLine.code)} · ${esc(s.sourceLine.name)}</strong></div>`:''}</div></div><div class="before-after"><h4>Destino · ${esc(s.dest.code)} ${esc(s.dest.name)}</h4><div class="impact-list"><div class="impact"><span>PIM antes</span><strong>${money(s.destBefore.pim)}</strong></div><div class="impact"><span>PIM después</span><strong>${money(s.destAfter.pim)}</strong></div><div class="impact"><span>Proyección</span><strong>${s.destAfter.execution}%</strong></div></div></div></div>${s.flags.length?`<div class="recommend danger" style="margin-top:10px"><span>!</span><span>${s.flags.map(esc).join('<br>')}</span></div>`:`<div class="recommend success" style="margin-top:10px"><span>✓</span><span>Escenario potencialmente evaluable.</span></div>`}<h4 style="font-size:9px">Procedimiento</h4>${procedureFlow('presupuesto')}<div class="sticky-actions"><button class="btn accent" data-action="assistant" data-prompt="Explica este escenario y qué afectaría">✦ Explicar con IA</button><button class="btn primary" data-action="save-scenario">Guardar escenario</button></div>`)}`}
document.addEventListener('input',e=>{if(e.target.id==='global-search'){const q=e.target.value.trim();if(q.length>=2)runSearch(q);else $('#search-results')?.classList.remove('show')}if(e.target.id==='profile-search')$('#profile-list').innerHTML=profileOptions(e.target.value);if(e.target.id==='command-input'){const q=e.target.value.trim();if(q.length<2)return;searchAll(q,state.profileId).then(res=>{$('#command-results').innerHTML=res.map(x=>`<div class="command-item" data-search-route="${x.route}" data-search-filters='${encode(x.filters||{})}'><strong>${esc(x.title)}</strong><span>${esc(x.subtitle)}</span></div>`).join('')})}});
document.addEventListener('change',e=>{if(e.target.id==='att-unit'){state.filters.unitId=e.target.value||null;renderAttendance()}if(e.target.id==='att-month'){state.month=e.target.value;renderAttendance()}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand()}if(e.key==='Enter'&&e.target.id==='assistant-query'&&!e.shiftKey){e.preventDefault();sendAssistant()}if(e.key==='Escape'){if(state.commandOpen)closeCommand();$('#modal-root').innerHTML='';if(state.assistantOpen){state.assistantOpen=false;assistantShell()}}});

async function init(){state.bootstrap=await getBootstrap(state.profileId);if(!DATA.profiles.some(p=>p.id===state.profileId)){state.profileId='USR-ADMIN';state.bootstrap=await getBootstrap(state.profileId)}state.selectedPersonId=state.bootstrap.profile.personId||null;sidebar();topbar();assistantShell();render()}
init();
